const webhookData = $('Webhook Trigger').item.json;
const body = webhookData.body || webhookData;
const rawQuestion = (body.question || '').trim();
let language = (body.language || '').toLowerCase().trim();
const sessionId = body.sessionId || ('srv_' + Math.random().toString(36).substring(2, 10));
const clientTimestamp = body.timestamp || new Date().toISOString();

if (!rawQuestion || rawQuestion.length === 0) {
  throw new Error('Question cannot be empty');
}

const question = rawQuestion.substring(0, 400);

if (!language || !['en', 'de', 'hu'].includes(language)) {
  const qLower = question.toLowerCase();
  if (/[áéíóöőúüű]/i.test(qLower) || qLower.includes('mennyi') || qLower.includes('milyen') || qLower.includes('weboldal') || qLower.includes('szolgáltatás')) {
    language = 'hu';
  } else if (/[äöüß]/i.test(qLower) || qLower.includes('welche') || qLower.includes('kosten') || qLower.includes('automatisierung')) {
    language = 'de';
  } else {
    language = 'en';
  }
}

let targetModel = 'qwen2.5:7b';
if (language === 'hu') {
  targetModel = 'hermes3:8b';
}

let rawFileContext = '';
try {
  rawFileContext = ($('Extract Context Text').item.json.contextText || '').trim();
} catch (e) {
  rawFileContext = '';
}

let servicesContext = rawFileContext;
if (language === 'de') {
  const deMatch = rawFileContext.match(/=== SECTION: DE ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (deMatch && deMatch[1].trim().length > 50) servicesContext = deMatch[1].trim();
} else if (language === 'hu') {
  const huMatch = rawFileContext.match(/=== SECTION: HU ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (huMatch && huMatch[1].trim().length > 50) servicesContext = huMatch[1].trim();
} else {
  const enMatch = rawFileContext.match(/=== SECTION: EN ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (enMatch && enMatch[1].trim().length > 50) servicesContext = enMatch[1].trim();
}

if (!servicesContext || servicesContext.length < 50) {
  servicesContext = 'Developer: Géza Horváth (Vienna, Austria). Contact: ghorvath@gmail.com. Services for SMBs & businesses: 1) Grounded AI Chatbots & Quote Calculators for new/existing websites, 2) Business Intelligence, Backend & Marketing Automations (n8n, APIs), 3) Full-Stack Dynamic Websites & Customizations, 4) Personal AI Assistants for Business & Work-Life Balance.';
}

let systemPrompt = '';
if (language === 'de') {
  systemPrompt = `Sie sind Géza Horváths KI-Serviceberater auf seiner Entwickler-Website. Beantworten Sie Fragen potenzieller Kunden (vor allem KMU/SMBs und Unternehmen) freundlich, präzise und ausschließlich auf Basis des folgenden VERIFIZIERTEN LEISTUNGS-DOSSIERS auf Deutsch (Höflichkeitsform "Sie").\n\n### STRIKTE REGELN:\n1. Nutzen Sie AUSSCHLIESSLICH Fakten aus dem Dossier. Erfinden Sie keine Pauschalpreise oder nicht genannten Leistungen.\n2. Bei konkreten Projektpreisen erklären Sie kurz, dass der Preis vom Projektumfang abhängt, und laden Sie den Besucher ein, das Kontaktformular auf der Seite auszufüllen oder direkt an ghorvath@gmail.com zu schreiben.\n3. Antworten Sie kompakt, strukturiert und kundenorientiert (2-5 Sätze oder kurze Aufzählungspunkte).\n\n### VERIFIZIERTES LEISTUNGS-DOSSIER:\n${servicesContext}`;
} else if (language === 'hu') {
  systemPrompt = `Te Horváth Géza AI szolgáltatási tanácsadó asszisztense vagy a fejlesztői weboldalán. Válaszolj a potenciális ügyfelek és vállalkozások (főként KKV-k) kérdéseire barátságosan, lényegretörően és KIZÁRÓLAG az alábbi HITELESÍTETT SZOLGÁLTATÁSI DOSSZIÉ alapján, természetes magyarsággal.\n\n### SZIGORÚ SZABÁLYOK:\n1. KIZÁRÓLAG a dossziéban szereplő tényeket használd. Ne találj ki konkrét fix árakat vagy nem létező referenciákat.\n2. Ha konkrét árazásról kérdeznek, mondd el, hogy minden projekt egyedi igényfelméréssel indul, és javasold a weboldalon található Kapcsolat űrlap kitöltését vagy a ghorvath@gmail.com e-mail címet.\n3. Válaszolj tömören, átláthatóan (2-5 mondat vagy rövid felsorolás).\n\n### HITELESÍTETT SZOLGÁLTATÁSI DOSSZIÉ:\n${servicesContext}`;
} else {
  systemPrompt = `You are Géza Horváth's AI Services Concierge on his web & AI developer studio website. Answer inquiries from potential clients and business owners (primarily SMBs as well as companies of any size) warmly, clearly, and strictly from the VERIFIED SERVICES DOSSIER below.\n\n### STRICT GROUNDING RULES:\n1. Use ONLY facts present in the verified dossier below. Never invent fixed price tags, fake clients, or unverified guarantees.\n2. If asked about exact pricing or a custom quote for their project, explain that projects are scoped pragmatically around their needs after a free discovery chat, and invite them to use the Contact Me form on this page or email ghorvath@gmail.com.\n3. Keep answers helpful, concise, and business-friendly (2-5 sentences or clean bullet points).\n\n### VERIFIED SERVICES DOSSIER:\n${servicesContext}`;
}

return {
  json: {
    question: question,
    language: language,
    targetModel: targetModel,
    sessionId: sessionId,
    clientTimestamp: clientTimestamp,
    systemPrompt: systemPrompt,
    startTime: Date.now()
  }
};

const prev = $('Sanitize & Build Prompt').item.json;
const ollamaResponse = $input.item.json;
const answer = (ollamaResponse.response || '').trim();
const durationMs = Date.now() - prev.startTime;

return {
  json: {
    status: 'success',
    answer: answer,
    sessionId: prev.sessionId,
    language: prev.language,
    model: prev.targetModel,
    durationMs: durationMs
  }
};
